export interface SceneOptions { position?: THREE.Vector3 | [number,number,number]; rotationY?: number; scale?: number; onLoad?: (model:THREE.Group)=>void }
export interface SceneInstance { group: THREE.Group; ready:Promise<THREE.Group|null>; update:(delta:number,player:THREE.Vector3)=>void; checkCollision:(candidate:THREE.Vector3,current:THREE.Vector3,radius:number)=>boolean; dispose:()=>void; readonly status:'loading'|'ready'|'error'|'disposed' }
export function createExportedScene(options:SceneOptions={}):SceneInstance {
 const group=new THREE.Group(), model=new THREE.Group(); group.name='ExportedScene'; group.add(model);
 if(options.position)group.position.copy(Array.isArray(options.position)?new THREE.Vector3(...options.position):options.position);
 if(options.rotationY!==undefined)group.rotation.y=options.rotationY;
 if(options.scale!==undefined)group.scale.setScalar(options.scale);
 const geos=new Map<string,THREE.BufferGeometry>();
 for(const [key,geo] of Object.entries(DATA.geometry)) { const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(geo.position,3));if(geo.uv.length)g.setAttribute('uv',new THREE.Float32BufferAttribute(geo.uv,2));g.computeVertexNormals();geos.set(key,g); }
 const textureLoader=new THREE.TextureLoader();
 const textures=DATA.images.map(()=>null as THREE.Texture|null);
 let status:'loading'|'ready'|'error'|'disposed'='loading';
 const textureJobs=DATA.images.map((image,i)=>new Promise<void>((resolve,reject)=>{textureLoader.load(image.uri,t=>{if(status==='disposed'){t.dispose();resolve();return;}t.colorSpace=THREE.SRGBColorSpace;textures[i]=t;resolve();},undefined,reject);}));
 const mats=DATA.materials.map(m=>new THREE.MeshStandardMaterial({color:new THREE.Color(m.color[0],m.color[1],m.color[2]),opacity:m.color[3],transparent:m.alpha,alphaTest:m.alpha?0.45:0,side:m.alpha?THREE.DoubleSide:THREE.FrontSide,roughness:.75}));
 const ready=Promise.all(textureJobs).then(()=>{if(status==='disposed')return null;DATA.materials.forEach((m,i)=>{if(m.image>=0){mats[i].map=textures[m.image];mats[i].needsUpdate=true;}});status='ready';return model;}).catch(e=>{if(status!=='disposed')status='error';console.error('Scene texture load failed',e);return null;});
 const hinges=DATA.triggers.map(t=>{const g=new THREE.Group();g.name='Hinge | '+t.name;g.matrixAutoUpdate=false;g.matrix.fromArray(t.hingeMatrix as unknown as number[]);model.add(g);return g;});
 const colliders:THREE.Mesh[]=[];
 for(const o of DATA.objects){const mesh=new THREE.Mesh(geos.get(o.geometry)!,mats[o.material]);mesh.name=o.name;mesh.matrixAutoUpdate=false;mesh.matrix.fromArray(o.matrix as unknown as number[]);mesh.receiveShadow=true;mesh.visible=o.visible;(o.trigger<0?model:hinges[o.trigger]).add(mesh);if(o.collider)colliders.push(mesh);}
 const scratch=new THREE.Vector3(), rotation=new THREE.Matrix4(), baseMatrices=hinges.map(h=>h.matrix.clone());
 const state=DATA.triggers.map(()=>({angle:0,hold:0}));
 
 function update(delta:number,player:THREE.Vector3){
  if(status==='disposed'||!player)return; group.updateWorldMatrix(true,false);model.updateWorldMatrix(true,false);
  const dt=Math.max(0,Math.min(delta,.1));
  for(let i=0;i<DATA.triggers.length;i++){const t=DATA.triggers[i],v=state[i];
   const triggerWorld=new THREE.Matrix4().multiplyMatrices(model.matrixWorld,new THREE.Matrix4().fromArray(t.zoneMatrix as unknown as number[]));
   scratch.copy(player).applyMatrix4(triggerWorld.invert());
   const inside=Math.abs(scratch.x)<=.5&&Math.abs(scratch.y)<=.5&&Math.abs(scratch.z)<=.5;
   if(inside)v.hold=t.delay;else v.hold=Math.max(0,v.hold-dt);
   const target=v.hold>0?t.angle:0;const step=Math.abs(t.angle)*dt/Math.max(.01,t.duration);
   v.angle+=Math.max(-step,Math.min(step,target-v.angle));
   rotation.makeRotationY(v.angle);hinges[i].matrix.copy(baseMatrices[i]).multiply(rotation);hinges[i].matrixWorldNeedsUpdate=true;
  }
 }
 const boxes=colliders.map(()=>new THREE.Box3());
 function checkCollision(candidate:THREE.Vector3,_current:THREE.Vector3,radius:number){
  if(status==='disposed')return false;group.updateWorldMatrix(true,true);
  for(let i=0;i<colliders.length;i++){const b=boxes[i].setFromObject(colliders[i]);
   if(candidate.y<b.min.y-2||candidate.y>b.max.y+1.8)continue;
   if(candidate.x>=b.min.x-radius&&candidate.x<=b.max.x+radius&&candidate.z>=b.min.z-radius&&candidate.z<=b.max.z+radius)return true;
  }return false;
 }
 function dispose(){if(status==='disposed')return;status='disposed';for(const g of geos.values())g.dispose();for(const m of mats)m.dispose();for(const t of textures)t?.dispose();group.removeFromParent();group.clear();}
 options.onLoad?.(model);return {group,ready,update,checkCollision,dispose,get status(){return status;}};
}

// Compatibility with the existing Zen Corner game integration.
export function createZenCorner(options:SceneOptions={}) { return createExportedScene({...options,position:options.position??[0,0.005,20]}); }
